//! Real local OS process tests against a FAKE protocol executable, not AI.
use std::{path::Path,time::{Duration,Instant},sync::{Arc,atomic::{AtomicBool,Ordering}}};
use moro_ai_bridge::provider::{capture,generate};
fn absent(pid:i32)->bool{unsafe{libc::kill(pid,0)==-1 && std::io::Error::last_os_error().raw_os_error()==Some(libc::ESRCH)}}
fn tree_case(mode:&str,cancel_it:bool){let dir=std::env::temp_dir().join(format!("moro-process-test-{}-{mode}-{cancel_it}",std::process::id()));std::fs::create_dir_all(&dir).unwrap();let marker=dir.join("pids");let args=vec!["--protocol-process-tree".to_string(),mode.to_string(),marker.to_str().unwrap().to_string()];let flag=Arc::new(AtomicBool::new(false));let worker_flag=flag.clone();let worker_dir=dir.clone();let h=std::thread::spawn(move||capture(Path::new(env!("CARGO_BIN_EXE_fake-cli-protocol-fixture")),&args,&worker_dir,b"",&worker_flag,if cancel_it{Duration::from_secs(5)}else{Duration::from_millis(300)}));let end=Instant::now()+Duration::from_secs(2);while !marker.exists(){assert!(Instant::now()<end,"fixture must start actual owned processes");std::thread::sleep(Duration::from_millis(5));}let pids:Vec<i32>=std::fs::read_to_string(&marker).unwrap().split_whitespace().map(|n|n.parse().unwrap()).collect();assert_eq!(pids.len(),2);if cancel_it{flag.store(true,Ordering::SeqCst);}let result=h.join().unwrap();if cancel_it{assert_eq!(result.unwrap_err(),"cancelled");}else if mode=="exit"{assert!(result.unwrap().0);}else{assert_eq!(result.unwrap_err(),"timeout");}let end=Instant::now()+Duration::from_secs(3);while pids.iter().any(|p|!absent(*p)){assert!(Instant::now()<end,"owned PID tree survived cleanup: {pids:?}");std::thread::sleep(Duration::from_millis(10));}let mut status=0;assert_eq!(unsafe{libc::waitpid(pids[0],&mut status,libc::WNOHANG)},-1,"root already reaped");assert_eq!(std::io::Error::last_os_error().raw_os_error(),Some(libc::ECHILD));std::fs::remove_dir_all(dir).unwrap();}
#[test]fn timeout_kills_group_and_reaps_owned_root(){tree_case("wait",false);}
#[test]fn cancellation_kills_group_and_reaps_owned_root(){tree_case("wait",true);}
#[test]fn normal_exit_kills_descendants_holding_pipes(){tree_case("exit",false);}
#[test]fn shutdown_prevents_any_new_worker(){let jobs=moro_ai_bridge::jobs::Jobs::new();jobs.shutdown();let result=jobs.start("codex".into(),env!("CARGO_BIN_EXE_fake-cli-protocol-fixture").into(),"fixture:success".into());jobs.shutdown();assert_eq!(result.unwrap_err(),"shutting_down");}
#[test]fn generate_has_bounded_deadline_and_cancellation(){let cancel=AtomicBool::new(false);assert_eq!(generate("codex",Path::new(env!("CARGO_BIN_EXE_fake-cli-protocol-fixture")),"fixture:slow",&cancel,Duration::from_millis(150)).unwrap_err(),"timeout");let cancel=AtomicBool::new(true);assert_eq!(generate("codex",Path::new(env!("CARGO_BIN_EXE_fake-cli-protocol-fixture")),"fixture:success",&cancel,Duration::from_secs(1)).unwrap_err(),"cancelled");}
